local Control=require(script.Parent.Parent.Base.Control)
return function(ctx,default,callback) local b=Instance.new("TextButton",ctx.Parent);b.Name="XYPad";b.Size=UDim2.new(1,0,0,150);b.BackgroundColor3=ctx.Theme:Get("SurfaceAlt");b.Text="";Instance.new("UICorner",b).CornerRadius=UDim.new(0,12);local dot=Instance.new("Frame",b);dot.Size=UDim2.fromOffset(16,16);dot.BackgroundColor3=ctx.Theme:Get("Accent");Instance.new("UICorner",dot).CornerRadius=UDim.new(1,0);local c=Control.new(b,ctx,default or Vector2.new(.5,.5));local UIS=game:GetService("UserInputService");local down=false;local function set(p) local x=math.clamp((p.X-b.AbsolutePosition.X)/b.AbsoluteSize.X,0,1);local y=math.clamp((p.Y-b.AbsolutePosition.Y)/b.AbsoluteSize.Y,0,1);c:SetValue(Vector2.new(x,y));dot.Position=UDim2.new(x,-8,y,-8);if callback then callback(c.Value)end end;ctx.Maid:Give(b.InputBegan:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then down=true;set(i.Position)end end));ctx.Maid:Give(UIS.InputChanged:Connect(function(i)if down and (i.UserInputType==Enum.UserInputType.MouseMovement or i.UserInputType==Enum.UserInputType.Touch)then set(i.Position)end end));ctx.Maid:Give(UIS.InputEnded:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then down=false end end));dot.Position=UDim2.new(c.Value.X,-8,c.Value.Y,-8);return c end
